def evaluate_postfix(expr):
    stack = []
    for token in expr.split():
        if token.isalpha():
            stack.append(token)
        else:
            if len(stack) < 2:
                raise ValueError('invalid postfix expression')
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                stack.append(a / b)
    if len(stack) != 1:
        raise ValueError('invalid postfix expression')
    return stack[0]

print(evaluate_postfix('a b +'))
print(evaluate_postfix('a b c + *'))

