def reverse_iterative(s):
    stack = []
    for ch in s:
        stack.append(ch)
    result = ''
    while stack:
        result += stack.pop()
    return result

def reverse_recursive(s):
    if len(s) <= 1:
        return s
    return reverse_recursive(s[1:]) + s[0]

print(reverse_iterative('stack'))
print(reverse_recursive('stack'))
print('iterative extra space:', 'O(n)')
